)

mapper.update:
UPDATE google_translation_daily_usage
SET used_characters = used_characters + #{characters},
    provider_calls = provider_calls + 1,
    updated_at = #{now}
WHERE usage_date = #{usageDate}
  AND subject_type = 'USER'
  AND user_id = #{userId}
  AND #{characters} <= #{characterLimit}
  AND used_characters <= #{characterLimit} - #{characters}

